{"command":"$p="C:\Users\spay\Documents\Obsidian Vault\Screen Notes"; $t=Get-Content "$p\screenpipe-chat-2026-04-11T23-37-09.md" -Raw
foreach($pipe in @('ai-tool-analyzer','youtube-ai-summarizer')){
  $i=$t.IndexOf("# $pipe")
  if($i -lt 0){ "### $pipe : NOT FOUND"; continue }
  "### $pipe ###"
  $seg=$t.Substring($i,[Math]::Min(2600,$t.Length-$i))
  $seg -replace '\\n',"`n" -replace '\\"','"'
  "`n=====================================`n"
}","description":"Extract pipe specs from raw chat"}
